        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 12725.0, "series": [{"data": [[0.0, 12704.0]], "isOverall": false, "label": "02 Search Product", "isController": false}, {"data": [[0.0, 12648.0]], "isOverall": false, "label": "04 Add to Cart", "isController": false}, {"data": [[0.0, 12674.0]], "isOverall": false, "label": "03 View Detail", "isController": false}, {"data": [[0.0, 12616.0], [300.0, 1.0], [100.0, 1.0], [500.0, 2.0]], "isOverall": false, "label": "05 Checkout", "isController": false}, {"data": [[0.0, 12725.0]], "isOverall": false, "label": "01 Login", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 500.0, "title": "Response Time Distribution"}},
